function sanitizeForQueryReplacement(text) {
  return typeof text === 'string' ? text.replace(/,/g, '，') : text;
}
// Brewfather บางฟิลด์ไม่มีใน object เลย (undefined) แทนที่จะเป็น null ตรงๆ
// ถ้าปล่อย undefined เข้า queryReplacement ตรงๆ n8n จะ stringify เป็น literal
// text "undefined" (ไม่ใช่ "null") ทำให้ NULLIF($n,'null')::numeric guard ที่มีอยู่
// จับไม่ได้ แล้ว cast เป็น numeric พัง ต้อง coalesce เป็น null ให้ชัดเจนก่อนเสมอ
function n(v) {
  return v === undefined ? null : v;
}

const items = $input.all();
let data;
if (items.length === 1 && Array.isArray(items[0].json)) {
  data = items[0].json;
} else {
  data = items.map(i => i.json);
}
return data.map(d => {
  const yeast = Array.isArray(d.yeasts) && d.yeasts.length ? d.yeasts[0] : null;
  const fermStep = d.fermentation && Array.isArray(d.fermentation.steps) && d.fermentation.steps.length
    ? d.fermentation.steps[0] : null;
  return {
    json: {
      recipe_id: d._id,
      name: sanitizeForQueryReplacement(n(d.name)),
      style_name: sanitizeForQueryReplacement(n(d.style ? d.style.name : null)),
      og: n(d.og),
      fg: n(d.fg),
      yeast_name: sanitizeForQueryReplacement(n(yeast ? yeast.name : null)),
      fermentation_temp_c: n(fermStep ? fermStep.stepTemp : null),
      raw_data: d
    }
  };
});

